const Imap = require('imap');
const { simpleParser } = require('mailparser');
const iconv = require('iconv-lite');
const axios = require('axios');
require('iconv-lite/encodings');

// Функция для снятия флага "прочитано"
function markAsUnread(imap, uid) {
    return new Promise((resolve, reject) => {
        imap.delFlags(uid, '\\Seen', (err) => {
            if (err) {
                console.error(`Ошибка снятия флага \\Seen для письма ${uid}:`, err);
                reject(err);
            } else {
                console.log(`Письмо ${uid} помечено как непрочитанное`);
                resolve();
            }
        });
    });
}

// Функция для установки флага "прочитано"
function markAsRead(imap, uid) {
    return new Promise((resolve, reject) => {
        imap.addFlags(uid, '\\Seen', (err) => {
            if (err) {
                console.error(`Ошибка установки флага \\Seen для письма ${uid}:`, err);
                reject(err);
            } else {
                console.log(`Письмо ${uid} помечено как прочитанное`);
                resolve();
            }
        });
    });
}

// Основная функция для обработки писем
function fetchAndProcessEmails(imap_host, imap_port, imap_user, imap_pass, emails, limit = 50) {
    return new Promise((resolve, reject) => {
        const results = [];
        const imap = new Imap({
            user: imap_user,
            password: imap_pass,
            host: imap_host,
            port: parseInt(imap_port),
            tls: true
        });

        imap.once('ready', function () {
            // Открываем папку "Рассылки|Прогрев" для чтения и записи
            imap.openBox('Рассылки|Прогрев', false, function (err, box) {
                if (err) {
                    console.error('Ошибка открытия папки "Рассылки|Прогрев":', err);
                    return reject(err);
                }

                // Ищем НЕпрочитанные письма
                imap.search(['UNSEEN'], async function (err, uids) {
                    if (err) return reject(err);

                    if (!uids.length) {
                        console.log('Непрочитанных писем не найдено');
                        imap.end();
                        return resolve([]);
                    }

                    console.log(`Найдено непрочитанных писем: ${uids.length}`);

                    // Разбиваем на группы по 100 писем
                    const chunkSize = 100;
                    const chunks = [];
                    for (let i = 0; i < Math.min(uids.length, limit); i += chunkSize) {
                        chunks.push(uids.slice(i, i + chunkSize));
                    }

                    console.log(`Разбиваем на ${chunks.length} групп по ${chunkSize} писем`);

                    try {
                        // Обрабатываем каждую группу последовательно
                        for (let chunkIndex = 0; chunkIndex < chunks.length; chunkIndex++) {
                            const chunkUids = chunks[chunkIndex];
                            console.log(`Обрабатываем группу ${chunkIndex + 1}/${chunks.length} (${chunkUids.length} писем)`);

                            const chunkResults = await processChunk(imap, chunkUids, emails);
                            results.push(...chunkResults);

                            console.log(`Группа ${chunkIndex + 1} обработана, найдено подходящих писем: ${chunkResults.length}`);
                        }

                        console.log('Все группы обработаны, итого подходящих писем:', results.length);
                        imap.end();
                        resolve(results);
                    } catch (error) {
                        console.error('Ошибка при обработке групп:', error);
                        imap.end();
                        reject(error);
                    }
                });
            });
        });

        // Функция для обработки группы писем
        async function processChunk(imap, uids, emails) {
            return new Promise((resolve, reject) => {
                const chunkResults = [];
                let processed = 0;

                const f = imap.fetch(uids, { 
                    bodies: '',
                    struct: true 
                });

                f.on('message', function (msg) {
                    let buffer = Buffer.alloc(0);
                    let uid;

                    msg.on('attributes', attrs => {
                        uid = attrs.uid;
                    });

                    msg.on('body', function (stream) {
                        const chunks = [];
                        stream.on('data', chunk => chunks.push(chunk));
                        stream.on('end', () => {
                            buffer = Buffer.concat(chunks);
                        });
                    });

                    msg.once('end', async function () {
                        try {
                            let parsed = await simpleParser(buffer);

                            if (parsed.text && /пї|Рї|СЂ|Сѓ/.test(parsed.text)) {
                                const decoded = iconv.decode(buffer, 'win1251');
                                parsed = await simpleParser(decoded);
                            }

                            const sender = parsed.from?.value?.[0]?.address || '';
                            const messageId = parsed.messageId || '';

                            // Проверяем в базе данных, нужно ли обрабатывать это письмо
                            try {
                                const resp = await axios.post(
                                    'http://37.18.2.51:8082/v1/need_processing',
                                    { 
                                        message_id: messageId, 
                                        exe_id: $execution.id 
                                    }
                                );

                                if (resp.data && resp.data.message === true) {
                                    // Если письмо нужно обработать - оставляем непрочитанным и добавляем в результаты
                                    await markAsUnread(imap, uid);

                                    chunkResults.push({
                                        id: chunkResults.length + 1,
                                        sender: sender,
                                        recipient: parsed.to?.value?.[0]?.address || '',
                                        message_id: messageId,
                                        folder: 'Рассылки|Прогрев',
                                        uid: uid,
                                        is_in_list: emails.includes(sender),
                                        subject: parsed.subject || '',
                                        date: parsed.date || new Date()
                                    });

                                    console.log(`Письмо ${uid} (${messageId}) - НЕ обработано в базе, оставляем для обработки`);
                                } else {
                                    // Если письмо уже обработано - помечаем как прочитанное
                                    await markAsRead(imap, uid);
                                    console.log(`Письмо ${uid} (${messageId}) - уже обработано в базе, помечаем как прочитанное`);
                                }
                            } catch (dbError) {
                                console.error(`Ошибка проверки в базе для письма ${uid}:`, dbError);
                                // При ошибке проверки оставляем письмо для обработки
                                await markAsUnread(imap, uid);

                                chunkResults.push({
                                    id: chunkResults.length + 1,
                                    sender: sender,
                                    recipient: parsed.to?.value?.[0]?.address || '',
                                    message_id: messageId,
                                    folder: 'Рассылки|Прогрев',
                                    uid: uid,
                                    is_in_list: emails.includes(sender),
                                    subject: parsed.subject || '',
                                    date: parsed.date || new Date(),
                                    db_error: true
                                });
                            }

                        } catch (e) {
                            console.error('Ошибка парсинга письма UID:', uid, e);
                        } finally {
                            processed++;

                            // Если все письма в группе обработаны
                            if (processed === uids.length) {
                                resolve(chunkResults);
                            }
                        }
                    });
                });

                f.once('error', err => {
                    console.error('Ошибка fetch для группы:', err);
                    reject(err);
                });

                f.once('end', function () {
                    console.log('Fetch группы завершен');
                });
            });
        }

        imap.once('error', err => reject(err));
        imap.connect();
    });
}

